/*
 * ZDI-CAN-30559: PCF RepadBitmap heap buffer overflow
 *
 * The font declares a tiny bitmapSizes[2] (for pad=4, 16 bytes) but has
 * per-glyph metrics (200x20) that cause RepadBitmap to write 560 bytes.
 * Without the fix, this overflows the allocated buffer by 544 bytes.
 *
 * With the fix in pcfread.c, the library computes the required buffer
 * size from per-glyph metrics instead of trusting bitmapSizes[].
 *
 * Test font: test/data/repad/evil-repad.pcf
 * Generated by: test/gen_evil_pcf_repad.py
 */

